/**
 * PortPilot demo seed - the maintainer's own projects (examworthy, azureprep,
 * statewise, cosmos-collective, 550-au, alight, PortPilot) for marketing
 * screenshots. Names, branches and the page thumbnails are real (each
 * thumbnail is a 480x270 capture of that project's own page); the states
 * (a crash, port conflicts, who started what, uptimes) are staged, and the
 * filesystem paths are generic. No client project appears. Loading this
 * before renderer.js installs a mock window.portpilot backed by this data,
 * so the real renderer renders a curated showcase (nested worktrees, health
 * states, a reserved port, a live port conflict, a crashed app, a
 * Claude-started app, groups) without a backend.
 *
 * Reproduce a screenshot:
 *   serve src/renderer/index.html with this file executed first
 *   (e.g. via the chrome-devtools navigate initScript).
 */
(function () {
  const now = new Date('2026-07-01T06:00:00Z').toISOString();

  // 480x270 captures of each project's own page (examworthy.com, statewiseexams.com, and local dev servers).
  const REAL_THUMBS = {
    examworthy: 'data:image/jpeg;base64,',
    azureprep: 'data:image/jpeg;base64,',
    statewise: 'data:image/jpeg;base64,',
    cosmos: 'data:image/jpeg;base64,',
    portpilot: 'data:image/jpeg;base64,',
    au550: 'data:image/jpeg;base64,',
  };

  const groups = [
    { id: 'g_harbor', name: 'Exam prep', color: '#7aa2f7', expanded: true },
    { id: 'g_tools', name: 'Side projects', color: '#9ece6a', expanded: true },
  ];

  // name, command, cwd, port, group, parentId, branch, colour, flags
  const apps = [
    { id: 'a_web', name: 'examworthy-web', command: 'pnpm dev', cwd: 'C:/dev/examworthy', preferredPort: 3000, group: 'g_harbor' },
    { id: 'a_web_checkout', name: 'examworthy-web', command: 'pnpm dev', cwd: 'C:/dev/examworthy-design-gap', preferredPort: 3002, group: 'g_harbor', parentId: 'a_web', branch: 'feat/design-gap-fixes', color: '#7aa2f7', colorSource: 'peacock' },
    { id: 'a_web_search', name: 'examworthy-web', command: 'pnpm dev', cwd: 'C:/dev/examworthy-claude-blog', preferredPort: 3003, group: 'g_harbor', parentId: 'a_web', branch: 'feat/claude-cert-blog-posts', color: '#bb9af7', colorSource: 'peacock' },
    { id: 'a_api', name: 'statewise', command: 'npm run dev -- --port 3500', cwd: 'C:/dev/statewise/web', preferredPort: 3500, group: 'g_harbor' },
    { id: 'a_admin', name: 'alight', command: 'npm run dev -- --port 3300', cwd: 'C:/dev/alight', preferredPort: 3300, group: 'g_tools', reservePort: true },
    { id: 'a_gw', name: 'portpilot', command: 'npm run agent', cwd: 'C:/dev/portpilot', preferredPort: 7317, group: 'g_tools' },
    { id: 'a_docs', name: 'cosmos-collective', command: 'npm run dev -- --port 3600', cwd: 'C:/dev/cosmos-collective', preferredPort: 3600, group: 'g_tools' },
    { id: 'a_metrics', name: '550-au', command: 'npm run dev -- --port 3210', cwd: 'C:/dev/550-au', preferredPort: 3210 },
    { id: 'a_preview', name: 'azureprep', command: 'npm run dev', cwd: 'C:/dev/azureprep', preferredPort: 3000, group: 'g_harbor' },
  ].map((a) => ({
    fallbackRange: null, env: {}, autoStart: false, isFavorite: false,
    description: null, startupDelay: null, parentId: null, branch: null,
    worktreePath: null, colorSource: null, color: '#7dcfff', healthPath: null,
    reservePort: false, createdAt: now, updatedAt: now, ...a,
  }));

  // Which apps are running (managed), and the detected port for each.
  const running = {
    a_web: { port: 3000, pid: 4101, processName: 'node.exe', commandLine: 'node next dev' },
    a_web_checkout: { port: 3002, pid: 4132, processName: 'node.exe', commandLine: 'node next dev' },
    a_web_search: { port: 3003, pid: 4140, processName: 'node.exe', commandLine: 'node next dev' },
    a_api: { port: 3500, pid: 4200, processName: 'node.exe', commandLine: 'node next dev' },
    a_gw: { port: 7317, pid: 4310, processName: 'node.exe', commandLine: 'node src/agent/server.js' },
  };

  const health = { a_web: 'healthy', a_web_checkout: 'healthy', a_web_search: 'unhealthy', a_api: 'healthy', a_gw: 'healthy' };

  // Start times relative to page load, so the row state cell shows real uptimes.
  const ago = (sec) => new Date(Date.now() - sec * 1000).toISOString();
  const startedAgo = { a_web: 2 * 3600 + 14 * 60, a_web_checkout: 18 * 60, a_web_search: 41 * 60, a_api: 52 * 60, a_gw: 3 * 86400 + 600 };

  const runningApps = Object.keys(running).map((id) => {
    const app = apps.find((a) => a.id === id);
    return { id, pid: running[id].pid, name: app.name, command: app.command, cwd: app.cwd, running: true, startTime: ago(startedAgo[id]), exitCode: null, crashed: false };
  });
  // 550-au started fine, then died on its own: a crash, not a stop.
  runningApps.push({ id: 'a_metrics', pid: 4420, name: '550-au', command: 'npm run dev -- --port 3210', cwd: 'C:/dev/550-au', running: false, startTime: ago(25 * 60), exitCode: 1, crashed: true });

  // Who started what (portpilot-runtime.json): Claude started the checkout
  // branch over MCP; the rest were started by hand.
  const runtime = {
    a_web: { startedBy: { kind: 'human', surface: 'desktop', at: ago(startedAgo.a_web) }, pid: 4101, port: 3000 },
    a_web_checkout: { startedBy: { kind: 'claude', surface: 'mcp', sessionId: 'a3f2c91e-demo', label: 'checkout drift fix', at: ago(startedAgo.a_web_checkout) }, pid: 4132, port: 3002 },
    a_api: { startedBy: { kind: 'human', surface: 'vscode', at: ago(startedAgo.a_api) }, pid: 4200, port: 3500 },
  };

  const matches = {};
  for (const id of Object.keys(running)) {
    matches[id] = { port: running[id].port, pid: running[id].pid, address: '127.0.0.1', processName: running[id].processName, commandLine: running[id].commandLine, conflict: false, matchType: 'preferredPort-cwd', confidence: 'high' };
  }

  // Two port conflicts, one of each kind the conflict strip describes:
  //   cosmos-collective (3600) is squatted by a foreign process -> "not managed".
  //   azureprep (3000) collides with examworthy-web, a registered app -> "Stop examworthy-web & start".
  const unknownConflicts = [
    { appId: 'a_docs', appName: 'cosmos-collective', port: 3600, occupiedBy: { processName: 'node.exe', pid: 9812, commandLine: 'node http-server' } },
    { appId: 'a_preview', appName: 'azureprep', port: 3000, occupiedBy: { processName: 'node.exe', pid: 4101, commandLine: 'node next dev' } },
  ];
  // Uptime (seconds) per listening pid, so the strip can say "started 3h ago".
  const uptimes = { 9812: 3 * 3600 + 540, 4101: 2 * 3600 + 14 * 60 };

  const ports = [
    { port: 3000, pid: 4101, processName: 'node.exe', commandLine: 'node next dev', address: '127.0.0.1', appId: 'a_web' },
    { port: 3002, pid: 4132, processName: 'node.exe', commandLine: 'node next dev', address: '127.0.0.1', appId: 'a_web_checkout' },
    { port: 3003, pid: 4140, processName: 'node.exe', commandLine: 'node next dev', address: '127.0.0.1', appId: 'a_web_search' },
    { port: 3500, pid: 4200, processName: 'node.exe', commandLine: 'node next dev', address: '127.0.0.1', appId: 'a_api' },
    { port: 7317, pid: 4310, processName: 'node.exe', commandLine: 'node src/agent/server.js', address: '127.0.0.1', appId: 'a_gw' },
    { port: 3600, pid: 9812, processName: 'node.exe', commandLine: 'node http-server', address: '127.0.0.1' },
    { port: 6006, pid: 5001, processName: 'node.exe', commandLine: 'storybook dev', address: '127.0.0.1' },
    { port: 5432, pid: 2200, processName: 'postgres.exe', commandLine: 'postgres', address: '127.0.0.1' },
    { port: 135, pid: 4, processName: 'System', commandLine: '', address: '0.0.0.0' },
    { port: 445, pid: 4, processName: 'System', commandLine: '', address: '0.0.0.0' },
  ];

  // ?home=classic loads the classic app list instead of the Now running strip (the default home).
  const homeParam = typeof location !== 'undefined' ? new URLSearchParams(location.search).get('home') : null;
  const settings = { ...(homeParam ? { homeLayout: homeParam } : {}), autoScan: false, scanInterval: 5000, theme: 'tokyonight', closeToTray: true, stopAppsOnQuit: true, openAtLogin: true, autoResizeWindow: false, notifyOnCrash: true, favoritesExpanded: true, otherProjectsExpanded: true, discovery: {} };

  const ok = (extra) => Promise.resolve(Object.assign({ success: true }, extra));
  const noop = () => ok();

  // ---- Run history (the History tab) ----
  // Fictional runs, newest first once sorted. Two are live (their apps are in
  // `running`: examworthy-web x2 and statewise), one crashed and pinned, one has no git, one is a re-run.
  const mins = (m) => ago(m * 60);
  const run = (o) => ({
    repoRoot: o.cwd, relCwd: '', url: o.port ? `http://localhost:${o.port}/` : null, stoppedAt: null, endedBy: null,
    exitCode: null, page: null, pinned: false, ...o,
  });
  const gitOf = (branch, sha, subject, files = []) => ({ branch, sha, subject, dirty: files.length > 0, files, snapshot: files.length ? { ref: `refs/portpilot/runs/${sha.slice(0, 7)}`, commit: sha, bytes: 12000 } : null, skipped: null });
  const human = (at) => ({ kind: 'human', surface: 'desktop', at });
  const historyRuns = [
    run({ id: 'r_demo01', appId: 'a_web', appName: 'examworthy-web', cwd: 'C:/dev/examworthy', command: 'pnpm dev', port: 3000, startedBy: human(mins(134)), startedAt: mins(134),
      git: gitOf('main', '4be07c1aa91d', 'chore: bump deps', ['apps/web/app/page.tsx', 'apps/web/lib/readiness.ts']), page: { title: 'Examworthy - certification exam prep', thumb: 'thumbs/r_demo01.jpg' } }),
    run({ id: 'r_demo02', appId: 'a_web_checkout', appName: 'examworthy-web', cwd: 'C:/dev/examworthy-design-gap', command: 'pnpm dev', port: 3002,
      startedBy: { kind: 'claude', surface: 'mcp', sessionId: 'a3f2c91e-demo', label: 'design gap fixes', at: mins(18) }, startedAt: mins(18),
      git: gitOf('feat/design-gap-fixes', '9c41e0a73b2f', 'wip: readiness card spacing', ['apps/web/app/page.tsx', 'apps/web/components/ReadinessCard.tsx', 'apps/web/styles/hero.css']), page: { title: 'Examworthy - certification exam prep', thumb: 'thumbs/r_demo02.jpg' } }),
    run({ id: 'r_demo03', appId: 'a_api', appName: 'statewise', cwd: 'C:/dev/statewise/web', command: 'npm run dev -- --port 3500', port: 3500, startedBy: human(mins(52)), startedAt: mins(52),
      git: gitOf('main', '77d0e12c4a90', 'fix: exam outline rounding'), page: { title: 'Statewise - state-specific insurance exam practice', thumb: 'thumbs/r_demo03.jpg' } }),
    run({ id: 'r_demo04', appId: 'a_metrics', appName: '550-au', cwd: 'C:/dev/550-au', command: 'npm run dev -- --port 3210', port: 3210, startedBy: human(mins(210)), startedAt: mins(210),
      stoppedAt: mins(205), endedBy: 'crash', exitCode: 1, pinned: true, git: gitOf('feat/pearl-materials', 'e5a1b30f9c11', 'feat: pearl close-up materials', ['src/acts/act4.js']) }),
    run({ id: 'r_demo05', appId: 'a_docs', appName: 'cosmos-collective', cwd: 'C:/dev/cosmos-collective', command: 'npm run dev -- --port 3600', port: 3600, startedBy: human(mins(60 * 26)), startedAt: mins(60 * 26),
      stoppedAt: mins(60 * 25), endedBy: 'stop', rerunOf: 'r_demo09', git: gitOf('main', '3a9f6c20d7e4', 'feat: galaxy view dock'), page: { title: 'Cosmos Collective | Multi-Spectrum Astronomical Explorer', thumb: 'thumbs/r_demo05.jpg' } }),
    run({ id: 'r_demo06', appId: 'a_admin', appName: 'alight', cwd: 'C:/dev/alight', command: 'npm run dev -- --port 3300', port: 3300,
      startedBy: { kind: 'claude', surface: 'mcp', sessionId: 'b71c9e04-demo', at: mins(60 * 30) }, startedAt: mins(60 * 30), stoppedAt: mins(60 * 29), endedBy: 'stop',
      git: gitOf('main', 'c08d4417be52', 'feat: song library', ['src/songs/index.ts']) }),
    run({ id: 'r_demo07', appId: 'a_gw', appName: 'portpilot', cwd: 'C:/dev/portpilot', command: 'npm run agent', port: 7317, startedBy: human(mins(60 * 52)), startedAt: mins(60 * 52),
      stoppedAt: mins(60 * 50), endedBy: 'unknown', git: null }),
    run({ id: 'r_demo08', appId: 'a_web', appName: 'examworthy-web', cwd: 'C:/dev/examworthy', command: 'pnpm dev', port: 3000, startedBy: human(mins(60 * 75)), startedAt: mins(60 * 75),
      stoppedAt: mins(60 * 73), endedBy: 'stop', git: gitOf('feat/claude-cert-blog-posts', '1f7b9d03a6c8', 'feat: Claude certification posts'), page: { title: 'Examworthy - certification exam prep', thumb: 'thumbs/r_demo08.jpg' } }),
    run({ id: 'r_demo10', appId: 'a_preview', appName: 'azureprep', cwd: 'C:/dev/azureprep', command: 'npm run dev', port: 3000, startedBy: human(mins(60 * 98)), startedAt: mins(60 * 98),
      stoppedAt: mins(60 * 96), endedBy: 'stop', git: gitOf('master', '5d2e8a1b90c3', 'fix: question counts'), page: { title: 'azureprep - Azure practice exams', thumb: 'thumbs/r_demo10.jpg' } }),
    run({ id: 'r_demo11', appId: 'a_gw', appName: 'portpilot', cwd: 'C:/dev/portpilot', command: 'npm run agent', port: 7317, startedBy: human(ago(startedAgo.a_gw)), startedAt: ago(startedAgo.a_gw),
      git: gitOf('master', '22ef7594a3a5', 'chore(release): v3.9.0'), page: { title: 'PortPilot', thumb: 'thumbs/r_demo11.jpg' } }),
    run({ id: 'r_demo12', appId: 'a_metrics', appName: '550-au', cwd: 'C:/dev/550-au', command: 'npm run dev -- --port 3210', port: 3210, startedBy: human(mins(60 * 120)), startedAt: mins(60 * 120),
      stoppedAt: mins(60 * 118), endedBy: 'stop', git: gitOf('feat/pearl-materials', 'a7c30e9d1f44', 'feat: pearl lighting pass'), page: { title: '550 AU', thumb: 'thumbs/r_demo12.jpg' } }),
  ];
  const historyThumbs = {
    r_demo01: REAL_THUMBS.examworthy, r_demo02: REAL_THUMBS.examworthy, r_demo03: REAL_THUMBS.statewise,
    r_demo05: REAL_THUMBS.cosmos, r_demo08: REAL_THUMBS.examworthy, r_demo10: REAL_THUMBS.azureprep,
    r_demo11: REAL_THUMBS.portpilot, r_demo12: REAL_THUMBS.au550,
  };
  const liveRunIds = ['r_demo01', 'r_demo02', 'r_demo03', 'r_demo11'];
  const progressListeners = [];
  const history = {
    list: () => ok({ runs: historyRuns, live: liveRunIds, stats: { runs: 312, bytes: 41 * 1024 * 1024, maxBytes: 150 * 1024 * 1024 } }),
    thumbs: (ids) => ok({ thumbs: Object.fromEntries((ids || []).filter((id) => historyThumbs[id]).map((id) => [id, historyThumbs[id]])) }),
    // Same rule as runView.rowThumbs: the newest open run per app, if it has a thumb.
    rowThumbs: () => ok({ byApp: Object.fromEntries(historyRuns.filter((r) => !r.stoppedAt && r.page && r.page.thumb).map((r) => [r.appId, { id: r.id, thumb: r.page.thumb, port: r.port ?? null }])) }),
    pin: (id, pinned) => { const r = historyRuns.find((x) => x.id === id); if (r) r.pinned = !!pinned; return ok(); },
    rerun: (id) => new Promise((resolve) => {
      ['checking', 'worktree', 'install', 'register', 'start', 'done'].forEach((stage, i) => {
        setTimeout(() => progressListeners.forEach((cb) => cb({ runId: id, stage, line: stage === 'install' ? 'added 412 packages' : undefined })), 300 * i);
      });
      setTimeout(() => resolve({ success: true, port: 3004, appId: 'a_rerun' }), 1800);
    }),
  };

  window.portpilot = {
    ports: {
      scan: () => ok({ ports }),
      scanWithApps: () => ok({ ports, matches, unknownConflicts }),
      check: (port) => {
        const p = ports.find((x) => x.port === port);
        return ok(p ? { inUse: true, info: p } : { inUse: false });
      },
      findAvailable: (from, to) => {
        const taken = new Set(ports.map((p) => p.port));
        for (let n = from; n <= to; n++) if (!taken.has(n)) return ok({ port: n });
        return ok({ port: null });
      },
      kill: noop, getDetails: (pid) => ok({ details: { uptime: uptimes[pid] || null } }),
    },
    process: {
      list: () => ok({ apps: runningApps, runtime }),
      start: noop, stop: noop, kill: noop, logs: () => ok({ stdout: '', stderr: '' }),
    },
    config: {
      getApps: () => ok({ apps }),
      getGroups: () => ok({ groups }),
      getSettings: () => ok({ settings }),
      updateSettings: () => ok({ settings }),
      saveApp: noop, deleteApp: noop, toggleFavorite: noop, patchApp: noop, deleteAllApps: noop,
      updateAppsOrder: noop, export: () => ok({ data: '{}' }), import: noop,
      saveGroup: noop, deleteGroup: noop,
    },
    worktrees: { detect: () => ok({ candidates: [] }), stale: () => ok({ ids: [] }) },
    health: { check: (appId) => ok({ appId, state: health[appId] || 'down' }) },
    net: { shareInfo: () => ok({ localUrl: 'http://localhost:3000', lanUrl: 'http://192.168.1.24:3000', qrDataUrl: '' }) },
    reserve: { enable: noop, disable: noop },
    discovery: { scan: () => ok({ projects: [] }), detectProject: () => ok({ project: null }), getSettings: () => ok({ settings: {} }), addScanPath: noop, removeScanPath: noop, updateSettings: noop },
    docker: { status: () => Promise.resolve({ running: false }), start: noop },
    window: { autoResize: noop },
    tray: { update: noop },
    crash: { askClaude: () => ok({ short: 'b71c' }) },
    // The crash toast main.js would send when 550-au dies, with a live
    // Claude session to hand it to (the shape crashAlert.buildCrashAlert makes).
    history,
    on: (channel, cb) => {
      if (channel === 'history-progress') { progressListeners.push(cb); return; }
      if (channel !== 'crash-toast') return;
      setTimeout(() => cb({
        appId: 'a_metrics', name: '550-au', title: '550-au crashed 2x in 5m',
        meta: ':3210 · exit 1', count: 2, at: Date.now(),
        lines: [
          'error when starting dev server:',
          'Error: Port 3210 is already in use',
        ],
        session: { id: 'b71c9e04-demo', short: 'b71c', reason: 'owner' },
      }), 400);
    },
    openExternal: noop,
    browseDirectory: () => ok({ canceled: true }),
  };
})();
